-- Mock-test domain. Metadata only: no Cambridge passages, media, answer keys or Band entries are seeded.
create table if not exists public.mock_templates (id uuid primary key default gen_random_uuid(), exam text not null check (exam = 'ielts_academic'), series text not null check (series = 'Cambridge IELTS Academic'), volume smallint not null check (volume between 16 and 21), test_number smallint not null check (test_number between 1 and 4), module text not null check (module in ('reading','listening')), archived_at timestamptz, created_at timestamptz not null default now(), unique (exam, volume, test_number, module));
create table if not exists public.mock_band_scales (id uuid primary key default gen_random_uuid(), module text not null check (module in ('reading','listening')), version integer not null check (version > 0), active boolean not null default false, verified_at timestamptz, created_at timestamptz not null default now(), unique(module, version), check (not active or verified_at is not null));
create table if not exists public.mock_template_versions (id uuid primary key default gen_random_uuid(), template_id uuid not null references public.mock_templates(id), version_number integer not null check (version_number > 0), duration_minutes integer not null check (duration_minutes between 1 and 300), question_count smallint not null default 40 check (question_count = 40), band_scale_id uuid references public.mock_band_scales(id), status text not null default 'draft' check (status in ('draft','published','archived')), created_by uuid references public.profiles(id), created_at timestamptz not null default now(), published_at timestamptz, unique(template_id, version_number));
create table if not exists public.mock_question_types (code text primary key check (code ~ '^[a-z_]+$'), module text check (module in ('reading','listening')), label text not null, active boolean not null default true);
create table if not exists public.mock_skills (code text primary key check (code ~ '^[a-z_]+$'), label text not null, active boolean not null default true);
create table if not exists public.mock_causes (code text primary key check (code ~ '^[a-z_]+$'), label text not null, requires_note boolean not null default false, active boolean not null default true);
create table if not exists public.mock_action_templates (id uuid primary key default gen_random_uuid(), code text not null unique check (code ~ '^[a-z_]+$'), title text not null, active boolean not null default true);
create table if not exists public.mock_template_questions (id uuid primary key default gen_random_uuid(), template_version_id uuid not null references public.mock_template_versions(id) on delete cascade, question_number smallint not null check (question_number between 1 and 40), section_number smallint not null check (section_number between 1 and 4), question_type_code text not null references public.mock_question_types(code), skill_code text not null references public.mock_skills(code), word_limit smallint check (word_limit between 1 and 20), unique(template_version_id, question_number));
create table if not exists public.mock_band_scale_entries (id uuid primary key default gen_random_uuid(), scale_id uuid not null references public.mock_band_scales(id) on delete cascade, raw_score_min smallint not null check (raw_score_min between 0 and 40), raw_score_max smallint not null check (raw_score_max between 0 and 40 and raw_score_max >= raw_score_min), estimated_band numeric(2,1) not null check (estimated_band between 0 and 9), unique(scale_id, raw_score_min, raw_score_max));
create table if not exists private.mock_answer_keys (question_id uuid primary key references public.mock_template_questions(id) on delete cascade, accepted_answers text[] not null check (cardinality(accepted_answers) > 0), created_at timestamptz not null default now());
create table if not exists public.mock_assignments (assignment_id uuid primary key references public.assignments(id) on delete cascade, template_version_id uuid not null references public.mock_template_versions(id), available_at timestamptz not null, attempt_limit smallint not null default 1 check (attempt_limit between 1 and 10), status text not null default 'draft' check (status in ('draft','scheduled','active','closed')), published_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.mock_accommodations (assignment_id uuid not null references public.mock_assignments(assignment_id) on delete cascade, student_id uuid not null references public.profiles(id), extra_minutes smallint not null check (extra_minutes between 1 and 180), created_by uuid references public.profiles(id), created_at timestamptz not null default now(), primary key (assignment_id, student_id));
create table if not exists public.mock_attempts (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.mock_assignments(assignment_id), student_id uuid not null references public.profiles(id), attempt_number smallint not null check (attempt_number > 0), status text not null default 'in_progress' check (status in ('in_progress','submitted','in_review','published','reopened')), started_at timestamptz not null default now(), expires_at timestamptz not null, submitted_at timestamptz, review_started_at timestamptz, published_at timestamptz, raw_score smallint check (raw_score between 0 and 40), estimated_band numeric(2,1) check (estimated_band between 0 and 9), server_revision integer not null default 0 check (server_revision >= 0), reopen_count smallint not null default 0 check (reopen_count >= 0), published_review_id uuid, unique(assignment_id, student_id, attempt_number));
create table if not exists public.mock_answers (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.mock_attempts(id) on delete cascade, question_id uuid not null references public.mock_template_questions(id), answer_text text not null default '', flagged_for_review boolean not null default false, normalized_answer text, is_correct boolean, saved_at timestamptz not null default now(), revision integer not null default 0, unique(attempt_id, question_id));
create table if not exists private.mock_answer_evaluations (answer_id uuid primary key references public.mock_answers(id) on delete cascade, normalized_answer text not null, auto_is_correct boolean not null, is_correct boolean not null, override_reason text, overridden_by uuid references public.profiles(id), overridden_at timestamptz, check ((overridden_at is null and overridden_by is null and override_reason is null) or length(trim(coalesce(override_reason,''))) > 0));
create table if not exists public.mock_review_versions (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.mock_attempts(id) on delete cascade, version integer not null check (version > 0), summary_text text, published_by uuid references public.profiles(id), published_at timestamptz, created_at timestamptz not null default now(), unique(attempt_id, version));
alter table public.mock_attempts add constraint mock_attempts_published_review_fk foreign key (published_review_id) references public.mock_review_versions(id) deferrable initially deferred;
create table if not exists public.mock_error_reviews (id uuid primary key default gen_random_uuid(), review_id uuid not null references public.mock_review_versions(id) on delete cascade, answer_id uuid not null references public.mock_answers(id) on delete cascade, question_type_code text not null references public.mock_question_types(code), skill_code text not null references public.mock_skills(code), primary_cause_code text not null references public.mock_causes(code), secondary_cause_code text references public.mock_causes(code), teacher_note text, action_text text, reviewed_by uuid not null references public.profiles(id), reviewed_at timestamptz not null default now(), unique(review_id, answer_id), check (primary_cause_code <> 'other' or length(trim(coalesce(teacher_note,''))) > 0));
create table if not exists public.mock_action_items (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.mock_attempts(id) on delete cascade, student_id uuid not null references public.profiles(id), title text not null check (length(trim(title)) between 1 and 500), status text not null default 'open' check (status in ('open','done')), created_by uuid references public.profiles(id), created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists public.mock_audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid not null, before_payload jsonb, after_payload jsonb, created_at timestamptz not null default now());
create index if not exists mock_assignments_version_idx on public.mock_assignments(template_version_id);
create index if not exists mock_attempts_assignment_student_idx on public.mock_attempts(assignment_id, student_id, attempt_number);
create index if not exists mock_attempts_review_queue_idx on public.mock_attempts(assignment_id, status);
create index if not exists mock_answers_attempt_idx on public.mock_answers(attempt_id);
create index if not exists mock_audit_entity_idx on public.mock_audit_events(entity_type, entity_id, created_at);

create or replace function private.normalize_mock_answer(p_value text) returns text language sql immutable security definer set search_path = '' as $$ select lower(regexp_replace(replace(replace(trim(p_value), '‘', ''''), '’', ''''), '\s+', ' ', 'g')) $$;
create or replace function private.enforce_mock_version_immutable() returns trigger language plpgsql security definer set search_path = '' as $$ begin if old.status = 'published' then raise exception 'Published mock template versions are immutable'; end if; return new; end $$;
create or replace function private.enforce_no_generic_mock_submission() returns trigger language plpgsql security definer set search_path = '' as $$ begin if exists (select 1 from public.mock_assignments where assignment_id = new.assignment_id) then raise exception 'Mock assignments use mock attempts, not generic submissions'; end if; return new; end $$;
create or replace function private.enforce_mock_audit_append_only() returns trigger language plpgsql security definer set search_path = '' as $$ begin raise exception 'Mock audit events are append-only'; end $$;
drop trigger if exists mock_version_immutable on public.mock_template_versions; create trigger mock_version_immutable before update on public.mock_template_versions for each row execute function private.enforce_mock_version_immutable();
drop trigger if exists enforce_no_generic_mock_submission on public.submissions; create trigger enforce_no_generic_mock_submission before insert or update of assignment_id on public.submissions for each row execute function private.enforce_no_generic_mock_submission();
drop trigger if exists mock_audit_append_only on public.mock_audit_events; create trigger mock_audit_append_only before update or delete on public.mock_audit_events for each row execute function private.enforce_mock_audit_append_only();

-- Close the generic policy bypass: linked mocks are controlled only by the RPCs below.
drop policy if exists assignments_manage on public.assignments;
create policy assignments_create_non_mock on public.assignments for insert to authenticated with check (teacher_id = (select auth.uid()) and (select private.can_manage_class(class_id)));
create policy assignments_update_non_mock on public.assignments for update to authenticated using ((select private.can_manage_class(class_id)) and not exists (select 1 from public.mock_assignments ma where ma.assignment_id = id)) with check (teacher_id = (select auth.uid()) and not exists (select 1 from public.mock_assignments ma where ma.assignment_id = id));
create policy assignments_delete_non_mock on public.assignments for delete to authenticated using ((select private.can_manage_class(class_id)) and not exists (select 1 from public.mock_assignments ma where ma.assignment_id = id));
drop policy if exists assignments_read on public.assignments;
create policy assignments_read on public.assignments for select to authenticated using ((select private.can_manage_class(class_id)) or ((select private.can_view_class(class_id)) and (not exists (select 1 from public.mock_assignments ma where ma.assignment_id = id) or exists (select 1 from public.mock_assignments ma where ma.assignment_id = id and ma.status <> 'draft'))));
drop policy if exists submissions_create on public.submissions;
create policy submissions_create on public.submissions for insert to authenticated with check ((select private.current_role()) = 'student' and student_id = (select auth.uid()) and exists (select 1 from public.assignments a where a.id = assignment_id and (select private.can_view_class(a.class_id))) and not exists (select 1 from public.mock_assignments ma where ma.assignment_id = submissions.assignment_id));

alter table public.mock_templates enable row level security; alter table public.mock_template_versions enable row level security; alter table public.mock_template_questions enable row level security; alter table public.mock_band_scales enable row level security; alter table public.mock_band_scale_entries enable row level security; alter table public.mock_question_types enable row level security; alter table public.mock_skills enable row level security; alter table public.mock_causes enable row level security; alter table public.mock_action_templates enable row level security; alter table public.mock_assignments enable row level security; alter table public.mock_accommodations enable row level security; alter table public.mock_attempts enable row level security; alter table public.mock_answers enable row level security; alter table public.mock_review_versions enable row level security; alter table public.mock_error_reviews enable row level security; alter table public.mock_action_items enable row level security; alter table public.mock_audit_events enable row level security;
revoke all on private.mock_answer_keys, private.mock_answer_evaluations from public, anon, authenticated;
revoke all on public.mock_templates, public.mock_template_versions, public.mock_template_questions, public.mock_band_scales, public.mock_band_scale_entries, public.mock_question_types, public.mock_skills, public.mock_causes, public.mock_action_templates, public.mock_assignments, public.mock_accommodations, public.mock_attempts, public.mock_answers, public.mock_review_versions, public.mock_error_reviews, public.mock_action_items, public.mock_audit_events from anon, authenticated;
grant select on public.mock_templates, public.mock_template_versions, public.mock_template_questions, public.mock_band_scales, public.mock_band_scale_entries, public.mock_question_types, public.mock_skills, public.mock_causes, public.mock_action_templates, public.mock_assignments, public.mock_accommodations, public.mock_attempts, public.mock_answers, public.mock_review_versions, public.mock_error_reviews, public.mock_action_items to authenticated;
create policy mock_templates_read on public.mock_templates for select to authenticated using (true);
create policy mock_versions_read on public.mock_template_versions for select to authenticated using (status = 'published' or created_by = (select auth.uid()));
create policy mock_questions_read on public.mock_template_questions for select to authenticated using (exists (select 1 from public.mock_template_versions v where v.id = template_version_id and (v.status = 'published' or v.created_by = (select auth.uid()))));
create policy mock_taxonomy_read on public.mock_question_types for select to authenticated using (true); create policy mock_skills_read on public.mock_skills for select to authenticated using (true); create policy mock_causes_read on public.mock_causes for select to authenticated using (true); create policy mock_actions_read on public.mock_action_templates for select to authenticated using (true); create policy mock_scales_read on public.mock_band_scales for select to authenticated using (active); create policy mock_scale_entries_read on public.mock_band_scale_entries for select to authenticated using (exists (select 1 from public.mock_band_scales s where s.id = scale_id and s.active));
create policy mock_assignments_read on public.mock_assignments for select to authenticated using (exists (select 1 from public.assignments a where a.id = assignment_id and ((select private.can_manage_class(a.class_id)) or ((select private.can_view_class(a.class_id)) and status <> 'draft'))));
create policy mock_accommodations_read on public.mock_accommodations for select to authenticated using (student_id = (select auth.uid()) or exists (select 1 from public.assignments a where a.id = assignment_id and (select private.can_manage_class(a.class_id))));
create policy mock_attempts_read on public.mock_attempts for select to authenticated using (student_id = (select auth.uid()) or exists (select 1 from public.assignments a where a.id = assignment_id and (select private.can_manage_class(a.class_id))));
create policy mock_answers_read on public.mock_answers for select to authenticated using (exists (select 1 from public.mock_attempts a where a.id = attempt_id and (a.student_id = (select auth.uid()) or exists (select 1 from public.assignments x where x.id = a.assignment_id and (select private.can_manage_class(x.class_id))))));
create policy mock_reviews_read on public.mock_review_versions for select to authenticated using (exists (select 1 from public.mock_attempts a where a.id = attempt_id and (exists (select 1 from public.assignments x where x.id = a.assignment_id and (select private.can_manage_class(x.class_id))) or (a.student_id = (select auth.uid()) and a.published_review_id = id))));
create policy mock_error_reviews_read on public.mock_error_reviews for select to authenticated using (exists (select 1 from public.mock_review_versions r join public.mock_attempts a on a.id = r.attempt_id where r.id = review_id and (exists (select 1 from public.assignments x where x.id = a.assignment_id and (select private.can_manage_class(x.class_id))) or (a.student_id = (select auth.uid()) and a.published_review_id = r.id))));
create policy mock_actions_owner_read on public.mock_action_items for select to authenticated using (student_id = (select auth.uid()) or exists (select 1 from public.mock_attempts a join public.assignments x on x.id = a.assignment_id where a.id = attempt_id and (select private.can_manage_class(x.class_id))));
create policy mock_actions_owner_update on public.mock_action_items for update to authenticated using (student_id = (select auth.uid())) with check (student_id = (select auth.uid()));

create or replace function public.create_mock_assignment(p_class_id uuid, p_template_version_id uuid, p_title text, p_brief text, p_available_at timestamptz, p_due_at timestamptz, p_attempt_limit smallint default 1) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_assignment uuid; begin if not (select private.can_manage_class(p_class_id)) then raise exception 'Class not found'; end if; if not exists (select 1 from public.mock_template_versions where id=p_template_version_id and status='published') then raise exception 'Template is not published'; end if; insert into public.assignments(class_id,teacher_id,title,brief,due_at,max_points) values(p_class_id,(select auth.uid()),trim(p_title),coalesce(p_brief,''),p_due_at,40) returning id into v_assignment; insert into public.mock_assignments(assignment_id,template_version_id,available_at,attempt_limit) values(v_assignment,p_template_version_id,p_available_at,p_attempt_limit); return v_assignment; end $$;
create or replace function public.publish_mock_assignment(p_assignment_id uuid) returns public.mock_assignments language plpgsql security definer set search_path = '' as $$ declare r public.mock_assignments%rowtype; begin select ma.* into r from public.mock_assignments ma join public.assignments a on a.id=ma.assignment_id where ma.assignment_id=p_assignment_id and (select private.can_manage_class(a.class_id)) for update; if r.assignment_id is null then raise exception 'Mock assignment not found'; end if; if (select count(*) from public.mock_template_questions where template_version_id=r.template_version_id) <> 40 or (select count(*) from private.mock_answer_keys k join public.mock_template_questions q on q.id=k.question_id where q.template_version_id=r.template_version_id) <> 40 then raise exception 'Mock key is incomplete'; end if; update public.mock_assignments set status=case when available_at <= now() then 'active' else 'scheduled' end,published_at=now() where assignment_id=p_assignment_id returning * into r; return r; end $$;
create or replace function public.set_mock_accommodation(p_assignment_id uuid,p_student_id uuid,p_extra_minutes smallint) returns void language plpgsql security definer set search_path = '' as $$ begin if not exists(select 1 from public.assignments a where a.id=p_assignment_id and (select private.can_manage_class(a.class_id))) then raise exception 'Mock assignment not found'; end if; insert into public.mock_accommodations(assignment_id,student_id,extra_minutes,created_by) values(p_assignment_id,p_student_id,p_extra_minutes,(select auth.uid())) on conflict(assignment_id,student_id) do update set extra_minutes=excluded.extra_minutes,created_by=excluded.created_by; insert into public.mock_audit_events(actor_id,action,entity_type,entity_id,after_payload) values((select auth.uid()),'accommodation_change','mock_assignment',p_assignment_id,jsonb_build_object('student_id',p_student_id,'extra_minutes',p_extra_minutes)); end $$;
create or replace function public.start_mock_attempt(p_assignment_id uuid) returns public.mock_attempts language plpgsql security definer set search_path = '' as $$ declare ma public.mock_assignments%rowtype; a public.assignments%rowtype; r public.mock_attempts%rowtype; n smallint; extra smallint; duration integer; begin select ma.*, a.* into ma from public.mock_assignments ma join public.assignments a on a.id=ma.assignment_id where ma.assignment_id=p_assignment_id for update; if ma.assignment_id is null or not (select private.can_view_class(a.class_id)) or (select private.current_role()) <> 'student' then raise exception 'Mock assignment not found'; end if; if ma.status not in ('active','scheduled') or ma.available_at > now() then raise exception 'Mock window has not opened'; end if; if a.due_at <= now() then raise exception 'Mock deadline has passed'; end if; select * into r from public.mock_attempts where assignment_id=p_assignment_id and student_id=(select auth.uid()) and status in ('in_progress','reopened') order by attempt_number desc limit 1 for update; if r.id is not null then return r; end if; select count(*)+1 into n from public.mock_attempts where assignment_id=p_assignment_id and student_id=(select auth.uid()); if n > ma.attempt_limit then raise exception 'Mock attempt limit reached'; end if; select duration_minutes into duration from public.mock_template_versions where id=ma.template_version_id; select extra_minutes into extra from public.mock_accommodations where assignment_id=p_assignment_id and student_id=(select auth.uid()); insert into public.mock_attempts(assignment_id,student_id,attempt_number,expires_at) values(p_assignment_id,(select auth.uid()),n,least(a.due_at,now()+make_interval(mins=>duration+coalesce(extra,0)))) returning * into r; insert into public.mock_audit_events(actor_id,action,entity_type,entity_id) values((select auth.uid()),'start','mock_attempt',r.id); return r; end $$;
create or replace function public.save_mock_answers(p_attempt_id uuid,p_expected_revision integer,p_answers jsonb) returns table(server_revision integer,saved_at timestamptz,attempt_status text) language plpgsql security definer set search_path = '' as $$ declare a public.mock_attempts%rowtype; item jsonb; q uuid; begin select * into a from public.mock_attempts where id=p_attempt_id and student_id=(select auth.uid()) for update; if a.id is null then raise exception 'Mock attempt not found'; end if; if a.status not in ('in_progress','reopened') or a.expires_at <= now() then raise exception 'Mock attempt is no longer editable'; end if; if a.server_revision <> p_expected_revision then raise exception 'Mock answer revision conflict'; end if; for item in select value from jsonb_array_elements(p_answers) loop q := (item->>'questionId')::uuid; if not exists(select 1 from public.mock_template_questions qx join public.mock_assignments ma on ma.template_version_id=qx.template_version_id where qx.id=q and ma.assignment_id=a.assignment_id) then raise exception 'Question does not belong to attempt'; end if; insert into public.mock_answers(attempt_id,question_id,answer_text,flagged_for_review,revision) values(a.id,q,coalesce(item->>'answerText',''),coalesce((item->>'flaggedForReview')::boolean,false),a.server_revision+1) on conflict(attempt_id,question_id) do update set answer_text=excluded.answer_text,flagged_for_review=excluded.flagged_for_review,saved_at=now(),revision=excluded.revision; end loop; update public.mock_attempts set server_revision=server_revision+1 where id=a.id returning server_revision,now(),status into server_revision,saved_at,attempt_status; return next; end $$;
create or replace function public.submit_mock_attempt(p_attempt_id uuid,p_expected_revision integer,p_automatic boolean default false) returns public.mock_attempts language plpgsql security definer set search_path = '' as $$ declare a public.mock_attempts%rowtype; q record; score integer:=0; band numeric(2,1); begin select * into a from public.mock_attempts where id=p_attempt_id and student_id=(select auth.uid()) for update; if a.id is null then raise exception 'Mock attempt not found'; end if; if a.status in ('submitted','in_review','published') then return a; end if; if a.status not in ('in_progress','reopened') then raise exception 'Mock attempt is not submittable'; end if; if not p_automatic and a.server_revision <> p_expected_revision then raise exception 'Mock answer revision conflict'; end if; for q in select tq.id from public.mock_template_questions tq join public.mock_assignments ma on ma.template_version_id=tq.template_version_id where ma.assignment_id=a.assignment_id loop insert into public.mock_answers(attempt_id,question_id) values(a.id,q.id) on conflict do nothing; end loop; for q in select ans.id,ans.answer_text,k.accepted_answers from public.mock_answers ans join private.mock_answer_keys k on k.question_id=ans.question_id where ans.attempt_id=a.id loop insert into private.mock_answer_evaluations(answer_id,normalized_answer,auto_is_correct,is_correct) values(q.id,private.normalize_mock_answer(q.answer_text),private.normalize_mock_answer(q.answer_text)=any(select private.normalize_mock_answer(x) from unnest(q.accepted_answers) x),private.normalize_mock_answer(q.answer_text)=any(select private.normalize_mock_answer(x) from unnest(q.accepted_answers) x)) on conflict(answer_id) do nothing; update public.mock_answers set normalized_answer=private.normalize_mock_answer(q.answer_text),is_correct=(select is_correct from private.mock_answer_evaluations where answer_id=q.id) where id=q.id; end loop; select count(*) into score from private.mock_answer_evaluations e join public.mock_answers ans on ans.id=e.answer_id where ans.attempt_id=a.id and e.is_correct; select e.estimated_band into band from public.mock_assignments ma join public.mock_template_versions v on v.id=ma.template_version_id join public.mock_band_scales s on s.id=v.band_scale_id and s.active and s.verified_at is not null join public.mock_band_scale_entries e on e.scale_id=s.id where ma.assignment_id=a.assignment_id and score between e.raw_score_min and e.raw_score_max limit 1; update public.mock_attempts set status='submitted',submitted_at=now(),raw_score=score,estimated_band=band,server_revision=server_revision+1 where id=a.id returning * into a; insert into public.mock_audit_events(actor_id,action,entity_type,entity_id) values((select auth.uid()),case when p_automatic then 'auto_submit' else 'submit' end,'mock_attempt',a.id); return a; end $$;
create or replace function public.begin_mock_review(p_attempt_id uuid) returns table(review_id uuid,version integer) language plpgsql security definer set search_path = '' as $$ declare a public.mock_attempts%rowtype; begin select x.* into a from public.mock_attempts x join public.assignments z on z.id=x.assignment_id where x.id=p_attempt_id and (select private.can_manage_class(z.class_id)) for update; if a.id is null or a.status not in ('submitted','in_review') then raise exception 'Mock attempt is not ready for review'; end if; select id,version into review_id,version from public.mock_review_versions where attempt_id=a.id and published_at is null order by version desc limit 1; if review_id is null then insert into public.mock_review_versions(attempt_id,version) values(a.id,(select coalesce(max(version),0)+1 from public.mock_review_versions where attempt_id=a.id)) returning id,version into review_id,version; update public.mock_attempts set status='in_review',review_started_at=now() where id=a.id; end if; return next; end $$;
create or replace function public.upsert_mock_error_reviews(p_review_id uuid,p_reviews jsonb) returns void language plpgsql security definer set search_path = '' as $$ declare r public.mock_review_versions%rowtype; x jsonb; begin select rv.* into r from public.mock_review_versions rv join public.mock_attempts a on a.id=rv.attempt_id join public.assignments z on z.id=a.assignment_id where rv.id=p_review_id and (select private.can_manage_class(z.class_id)) and rv.published_at is null; if r.id is null then raise exception 'Mock review not found'; end if; for x in select value from jsonb_array_elements(p_reviews) loop insert into public.mock_error_reviews(review_id,answer_id,question_type_code,skill_code,primary_cause_code,secondary_cause_code,teacher_note,action_text,reviewed_by) values(p_review_id,(x->>'answerId')::uuid,x->>'questionTypeCode',x->>'skillCode',x->>'primaryCauseCode',nullif(x->>'secondaryCauseCode',''),nullif(x->>'teacherNote',''),nullif(x->>'actionText',''),(select auth.uid())) on conflict(review_id,answer_id) do update set question_type_code=excluded.question_type_code,skill_code=excluded.skill_code,primary_cause_code=excluded.primary_cause_code,secondary_cause_code=excluded.secondary_cause_code,teacher_note=excluded.teacher_note,action_text=excluded.action_text,reviewed_by=excluded.reviewed_by,reviewed_at=now(); end loop; end $$;
create or replace function public.override_mock_answer(p_answer_id uuid,p_is_correct boolean,p_reason text) returns void language plpgsql security definer set search_path = '' as $$ begin if length(trim(coalesce(p_reason,'')))=0 then raise exception 'Override reason is required'; end if; if not exists(select 1 from public.mock_answers x join public.mock_attempts a on a.id=x.attempt_id join public.assignments z on z.id=a.assignment_id where x.id=p_answer_id and (select private.can_manage_class(z.class_id))) then raise exception 'Mock answer not found'; end if; update private.mock_answer_evaluations set is_correct=p_is_correct,override_reason=trim(p_reason),overridden_by=(select auth.uid()),overridden_at=now() where answer_id=p_answer_id; update public.mock_answers set is_correct=p_is_correct where id=p_answer_id; insert into public.mock_audit_events(actor_id,action,entity_type,entity_id,after_payload) values((select auth.uid()),'override_grade','mock_answer',p_answer_id,jsonb_build_object('is_correct',p_is_correct)); end $$;
create or replace function public.publish_mock_review(p_review_id uuid,p_summary_text text,p_actions jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$ declare r public.mock_review_versions%rowtype; missing text; x jsonb; begin if length(trim(coalesce(p_summary_text,'')))=0 then raise exception 'Mock review summary is required'; end if; select rv.* into r from public.mock_review_versions rv join public.mock_attempts a on a.id=rv.attempt_id join public.assignments z on z.id=a.assignment_id where rv.id=p_review_id and (select private.can_manage_class(z.class_id)) for update; if r.id is null or r.published_at is not null then raise exception 'Mock review not found'; end if; select string_agg(q.question_number::text,', ' order by q.question_number) into missing from public.mock_answers ans join public.mock_template_questions q on q.id=ans.question_id where ans.attempt_id=r.attempt_id and ans.is_correct=false and not exists(select 1 from public.mock_error_reviews er where er.review_id=r.id and er.answer_id=ans.id); if missing is not null then raise exception 'Mock review is incomplete: %',missing; end if; update public.mock_review_versions set summary_text=trim(p_summary_text),published_by=(select auth.uid()),published_at=now() where id=r.id; update public.mock_attempts set status='published',published_at=now(),published_review_id=r.id where id=r.attempt_id; for x in select value from jsonb_array_elements(p_actions) loop insert into public.mock_action_items(attempt_id,student_id,title,created_by) select r.attempt_id,a.student_id,trim(x->>'title'),(select auth.uid()) from public.mock_attempts a where a.id=r.attempt_id; end loop; insert into public.mock_audit_events(actor_id,action,entity_type,entity_id) values((select auth.uid()),'publish','mock_review',r.id); return public.get_mock_result(r.attempt_id); end $$;
create or replace function public.reopen_mock_attempt(p_attempt_id uuid,p_extra_minutes smallint default 0) returns public.mock_attempts language plpgsql security definer set search_path = '' as $$ declare a public.mock_attempts%rowtype; begin select x.* into a from public.mock_attempts x join public.assignments z on z.id=x.assignment_id where x.id=p_attempt_id and (select private.can_manage_class(z.class_id)) for update; if a.id is null or a.status not in ('submitted','in_review') then raise exception 'Only unpublished submitted attempts can reopen'; end if; update public.mock_attempts set status='reopened',expires_at=greatest(expires_at,now())+make_interval(mins=>coalesce(p_extra_minutes,0)),reopen_count=reopen_count+1 where id=a.id returning * into a; insert into public.mock_audit_events(actor_id,action,entity_type,entity_id) values((select auth.uid()),'reopen','mock_attempt',a.id); return a; end $$;
create or replace function public.get_mock_result(p_attempt_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$ declare allowed boolean; begin select exists(select 1 from public.mock_attempts a join public.assignments x on x.id=a.assignment_id where a.id=p_attempt_id and ((select private.can_manage_class(x.class_id)) or (a.student_id=(select auth.uid()) and a.status='published'))) into allowed; if not allowed then raise exception 'Mock result not found'; end if; return jsonb_build_object('attempt',(select to_jsonb(a) from public.mock_attempts a where a.id=p_attempt_id),'answers',(select coalesce(jsonb_agg(jsonb_build_object('questionNumber',q.question_number,'answerText',ans.answer_text,'correct',ans.is_correct,'acceptedAnswers',case when (select private.can_manage_class(x.class_id)) or a.status='published' then k.accepted_answers else null end) order by q.question_number),'[]'::jsonb) from public.mock_attempts a join public.assignments x on x.id=a.assignment_id join public.mock_answers ans on ans.attempt_id=a.id join public.mock_template_questions q on q.id=ans.question_id left join private.mock_answer_keys k on k.question_id=q.id where a.id=p_attempt_id),'review',(select to_jsonb(r) from public.mock_attempts a join public.mock_review_versions r on r.id=a.published_review_id where a.id=p_attempt_id)); end $$;
create or replace function public.complete_mock_action(p_action_id uuid) returns public.mock_action_items language plpgsql security definer set search_path = '' as $$ declare r public.mock_action_items%rowtype; begin update public.mock_action_items set status='done',completed_at=now() where id=p_action_id and student_id=(select auth.uid()) returning * into r; if r.id is null then raise exception 'Mock action not found'; end if; return r; end $$;
create or replace function public.finalize_expired_mock_attempts() returns integer language plpgsql security definer set search_path = '' as $$ declare r record; n integer:=0; begin if current_user <> 'service_role' then raise exception 'Only service_role can finalize expired mock attempts'; end if; for r in select id,server_revision from public.mock_attempts where status in ('in_progress','reopened') and expires_at <= now() loop perform public.submit_mock_attempt(r.id,r.server_revision,true); n:=n+1; end loop; return n; end $$;
create or replace function public.admin_import_mock_template(p_payload jsonb) returns uuid language plpgsql security definer set search_path = '' as $$ begin if current_user <> 'service_role' then raise exception 'Only service_role can import mock templates'; end if; if jsonb_typeof(p_payload) <> 'object' then raise exception 'Mock import payload must be an object'; end if; raise exception 'Use a validated server-side importer; this RPC deliberately accepts no committed keys'; end $$;
revoke all on function public.create_mock_assignment(uuid,uuid,text,text,timestamptz,timestamptz,smallint), public.publish_mock_assignment(uuid), public.set_mock_accommodation(uuid,uuid,smallint), public.start_mock_attempt(uuid), public.save_mock_answers(uuid,integer,jsonb), public.submit_mock_attempt(uuid,integer,boolean), public.begin_mock_review(uuid), public.upsert_mock_error_reviews(uuid,jsonb), public.override_mock_answer(uuid,boolean,text), public.publish_mock_review(uuid,text,jsonb), public.reopen_mock_attempt(uuid,smallint), public.get_mock_result(uuid), public.complete_mock_action(uuid), public.finalize_expired_mock_attempts(), public.admin_import_mock_template(jsonb) from public, anon, authenticated;
grant execute on function public.create_mock_assignment(uuid,uuid,text,text,timestamptz,timestamptz,smallint), public.publish_mock_assignment(uuid), public.set_mock_accommodation(uuid,uuid,smallint), public.start_mock_attempt(uuid), public.save_mock_answers(uuid,integer,jsonb), public.submit_mock_attempt(uuid,integer,boolean), public.begin_mock_review(uuid), public.upsert_mock_error_reviews(uuid,jsonb), public.override_mock_answer(uuid,boolean,text), public.publish_mock_review(uuid,text,jsonb), public.reopen_mock_attempt(uuid,smallint), public.get_mock_result(uuid), public.complete_mock_action(uuid) to authenticated;
grant execute on function public.finalize_expired_mock_attempts(), public.admin_import_mock_template(jsonb) to service_role;

insert into public.mock_templates(exam,series,volume,test_number,module) select 'ielts_academic','Cambridge IELTS Academic',v,t,m from generate_series(16,21) v cross join generate_series(1,4) t cross join unnest(array['reading','listening']) m on conflict do nothing;
