insert into public.mock_causes(code,label,requires_note) values ('knowledge_gap','Knowledge gap',false),('misunderstood_instruction','Misunderstood instruction',false),('missed_paraphrase','Missed paraphrase',false),('vocabulary_gap','Vocabulary gap',false),('wrong_strategy','Wrong strategy',false),('lost_focus','Lost focus',false),('rushed','Rushed',false),('ran_out_of_time','Ran out of time',false),('word_limit','Word limit',false),('transfer_error','Transfer error',false),('skipped','Skipped',false),('other','Other',true) on conflict do nothing;
